/**
 * Pairs each damage with the insured item it refers to. Every damage consumes a
 * distinct item, so a policy covering one sword cannot absorb two sword damages.
 */
const damagedItems = (policy: Policy, damages: Damage[]): Item[] => {
  const unclaimed = [...policy.items];

  return damages.map((damage) => {
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    if (index === -1) throw new UncoveredDamageError(damage.itemType);
    return unclaimed.splice(index, 1)[0];
  });
};

